int PipelineModule::onOptimize(Interpreter::SessionMode stage) {
    if (stage == Interpreter::Module_Forward_Separate) {
        if (mSubModules.size() == 1 && std::get<0>(mSubModules[0])->type() == "StaticModule") {
            mSeperate = true;
            return 0;
