void setScaleTranslate(float sx, float sy, float tx, float ty) {
    fMat[kMScaleX] = sx;
    fMat[kMSkewX]  = 0;
    fMat[kMTransX] = tx;

    fMat[kMSkewY]  = 0;
    fMat[kMScaleY] = sy;
    fMat[kMTransY] = ty;

    fMat[kMPersp0] = 0;
    fMat[kMPersp1] = 0;
    fMat[kMPersp2] = 1;

    unsigned mask = 0;
    if (sx != 1 || sy != 1) {
        mask |= kScale_Mask;
    }
    if (tx || ty) {
        mask |= kTranslate_Mask;
    }
    this->setTypeMask(mask | kRectStaysRect_Mask);
}

include/MNN/Matrix.h::computeTypeMask.source_code:
uint8_t computeTypeMask() const;
uint8_t computePerspectiveTypeMask() const;

void setTypeMask(int mask) {
    // allow kUnknown or a valid mask
    MNN_ASSERT(kUnknown_Mask == mask || (mask & kAllMasks) == mask ||
               ((kUnknown_Mask | kOnlyPerspectiveValid_Mask) & mask) ==
                   (kUnknown_Mask | kOnlyPerspectiveValid_Mask));
    fTypeMask = (uint8_t)(mask);
}

void orTypeMask(int mask) {
    MNN_ASSERT((mask & kORableMasks) == mask);
    fTypeMask = (uint8_t)(fTypeMask | mask);
}

include/MNN/Matrix.h::clearTypeMask.source_code:
void clearTypeMask(int mask) {
    // only allow a valid mask
    MNN_ASSERT((mask & kAllMasks) == mask);
    fTypeMask = fTypeMask & ~mask;
}

include/MNN/Matrix.h::updateTranslateMas.source_code:
inline void updateTranslateMask() {
    if ((fMat[kMTransX] != 0) | (fMat[kMTransY] != 0)) {
        fTypeMask |= kTranslate_Mask;
    } else {
        fTypeMask &= ~kTranslate_Mask;
    }
}

