        return true;
    }
#if defined(WIN32) || defined(_WIN32) || defined(_WIN64) || defined(_MSC_VER)
    if (CreateDirectory(path, NULL) || ERROR_ALREADY_EXISTS == GetLastError()) {
        return true;
    } else {
        return false;
    }
#else
    if (mkdir(path, 0755) == 0) {
        return true;
    }
    return MNNDirExist(path);
#endif
}

