source/core/OpCommonUtils.cpp::getBatchC.source_code:
static void getBatchChannelArea(const Tensor* t, int& batch, int& channel, int& area) {
    if (t->dimensions() == 0) {
        batch = 1;
        channel = 1;
        area = 1;
        return;
    }
    if (t->dimensions() == 1) {
        batch = t->length(0);
        channel = 1;
        area = 1;
        return;
    }
    batch = t->length(0);
    channel = t->length(1);
    area = 1;
    for (int i=2; i<t->dimensions(); ++i) {
        area *= t->length(i);
    }
}

source/core/OpCommonUtils.cpp::isTranspo.source_code:
bool OpCommonUtils::isTranspose(const Tensor::InsideDescribe::Region& region, int& srcOne, int& dstOne) {
    srcOne = -1;
    dstOne = -1;
    for (int i = 0; i < 3; i++) {
        if (region.size[i] == 1) {
            continue;
        }
        if (region.src.stride[i] == 1) {
            if (srcOne >= 0) {
                return false;
            }
            srcOne = i;
        }
        if (region.dst.stride[i] == 1) {
            if (dstOne >= 0) {
                return false;
            }
            dstOne = i;
        }
    }
    return srcOne >= 0 && dstOne >= 0 && srcOne != dstOne;
}

