    }
    auto hostbn = hostTensor->mDescribe->getBackend();
    std::shared_ptr<Tensor> tmpTensor;
    if (nullptr != hostbn && hostbn->type() != bn->type() && hostbn->type() != MNN_FORWARD_CPU) {
