    auto desO = TensorUtils::getDescribeOrigin(dst);
    auto srcDesO = TensorUtils::getDescribeOrigin(src);
    bool needMalloc = dst->buffer().host != src->buffer().host || dst->buffer().device != src->buffer().device || desO->offset != srcDesO->offset;
