WorkerThread::WorkerThread(int numberThread) {
    for (int i=0; i<numberThread; ++i) {
        mWorkers.emplace_back([this]() {
            while (!mStop) {
                Task* f = nullptr;
                {
                    std::unique_lock<std::mutex> _l(mQueueMutex);
                    mCondition.wait(_l, [this] { return mStop || mTasks.size() > 0;});
                    if (mTasks.empty()) {
                        continue;
                    }
                    f = mTasks.front();
                    mTasks.pop();
                }
                f->content();
                delete f;
            }
        });
    }
}

