bool WorkerThread::postTask(std::function<int()>&& task) {
    {
        AUTOTIME;
        std::unique_lock<std::mutex> _l(mQueueMutex);
        auto taskWrap = new Task;
        taskWrap->content = std::move(task);
        mTasks.push(taskWrap);
    }
    mCondition.notify_all();
    return true;
}

